package main
import("bytes";"encoding/json";"os";"path/filepath";"testing")
func TestRestorePreservesNewUserChanges(t *testing.T){r,dir:=fixtureRuntime(t);v:=mutateFile(t,r,runtimeRequest{Operation:"file_write",Path:"notes.txt",Expected:"missing",Content:"created"});id:=v.(map[string]any)["request_id"].(string);os.WriteFile(filepath.Join(dir,"notes.txt"),[]byte("new user edit"),0600);if _,e:=r.call(runtimeRequest{Operation:"file_restore",RestoreID:id,RequestID:newID()});e==nil{t.Fatal("restore erased user edit")};b,_:=os.ReadFile(filepath.Join(dir,"notes.txt"));if string(b)!="new user edit"{t.Fatal("edit changed")}}
func TestUncertainReceiptNeverReplays(t *testing.T){r,dir:=fixtureRuntime(t);p:=runtimeRequest{Operation:"file_write",Project:"sample",Path:"never.txt",Expected:"missing",Content:"do not replay",RequestID:newID()};b,_:=json.Marshal(p);x:=&Receipt{ID:p.RequestID,Digest:digest(b),Operation:p.Operation,Status:"dispatched",At:utcNow()};if e:=r.saveReceipt(x);e!=nil{t.Fatal(e)};if _,e:=r.call(p);e==nil{t.Fatal("uncertain request replayed")};if _,e:=os.Stat(filepath.Join(dir,"never.txt"));!os.IsNotExist(e){t.Fatal("uncertain operation executed")}}
type testWriteCloser struct{bytes.Buffer}
func(w *testWriteCloser)Close()error{return nil}
func TestCodexApprovalRejectsSessionGrantAndReplay(t *testing.T){w:=&testWriteCloser{};thread:=newID();id:=newID();c:=&codexClient{input:w,pending:map[string]codexPending{id:{ID:json.RawMessage("42"),Method:"item/fileChange/requestApproval",ThreadID:thread}}};p:=runtimeRequest{ThreadID:thread,ApprovalID:id,Decision:"acceptForSession"};if _,e:=c.respond(p);e==nil{t.Fatal("session grant accepted")};if len(c.pending)!=1{t.Fatal("invalid input consumed pending approval")};p.Decision="decline";if _,e:=c.respond(p);e!=nil{t.Fatal(e)};before:=w.String();if _,e:=c.respond(p);e==nil{t.Fatal("approval replay accepted")};if w.String()!=before{t.Fatal("approval response sent twice")}}
func TestStateCannotBeExposedAsProject(t *testing.T){_,dir:=fixtureRuntime(t);if r,e:=newRuntime(filepath.Join(dir,"public-state"));e==nil{r.Close();t.Fatal("state under project root accepted")}}
